			int mid=line.length()/2;
			int i2=mid-1;
			for(int i=0;i<mid&&palindrome;i++,i2--) {
				if(i!=i2&&line.charAt(i)!=line.charAt(i2))
					palindrome=false;
				else if(i==i2&&line.charAt(i-1)==line.charAt(i2))
					palindrome=false;
			}
			String l=line.substring(0,mid);
			String r=line.substring(mid+1,line.length());
			if(palindrome) {
				if(r.equals(l)&&line.charAt(mid)!=line.charAt(mid-1))
					out.write("Yes\n");
				else
					out.write("No\n");
			}else
				out.write("No\n");
