        int n = ni();
        boolean[] checks = new boolean[52];
        for (int i = 0; i < n; i++) {
            String mark = ns();
            int num = ni();
            int in = serialize(mark, num);
            checks[in] = true;
        }
        for (int i = 0; i < 52; i++) {
            if (checks[i]) {
                continue;
            }
            System.out.println(unserialize(i));
        }
