	private static boolean isPrime(int val) {
		if(val == 2 || val == 3) {return true;}
		if(val % 2 == 0) {return false;}

		for(int i = 3; i <= Math.sqrt((double)val); i += 2) {
			if(val % i == 0) {return false;}
		}

		return true;
	}
}

