    static class BPapersPlease {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints();
            for (int i = 0; i < n; i++) {
                int x = in.ints();
                if (x % 2 == 1) continue;
                if (x % 3 != 0 && x % 5 != 0) {
