                if (i + 4 >= cs.length) {
                    ans = "NO";
                    break;
                }
                if (cs[i + 1] != 'r' || cs[i + 2] != 'e' ||
                        cs[i + 3] != 'a' || cs[i + 4] != 'm') {
                    ans = "NO";
                    break;
                }
                if (i + 5 == cs.length || cs[i + 5] == 'd') {
