                }
                if (i + 6 >= cs.length) {
                    ans = "NO";
                    break;
                }
                if (cs[i + 5] == 'e' && cs[i + 6] == 'r' && (i + 7 == cs.length || 
                        cs[i + 7] != 'a')) {
                    continue;
                }
                if (cs[i + 5] != 'e' || cs[i + 6] != 'r') {
                    ans = "NO";
                    break;
                }
                i += 6;
            } else if (cs[i] == 'e') {
                if (i + 4 >= cs.length) {
                    ans = "NO";
                    break;
                }
