class Solver {
	public static boolean solve(int[][] a) {
		int[] prev = new int[] { 0, 0, 0 };
		for (int i = 0; i < a.length; i++) {
			// if ((a[i][0]+a[i][1]+a[i][2])%2!=0)
			// return false;
			int dist = Math.abs(a[i][1] - prev[1]) + Math.abs(a[i][2] - prev[2]);
			if (dist > a[i][0] - prev[0])
				return false;
			if (dist % 2 != (a[i][0] - prev[0]) % 2)
				return false;
		}
		return true;
	}
}

