		for(int i = 0; i < n; i++) {
			c[i] = sc.nextInt();
			time[i] = sc.nextInt();
		}

		int answer = 1001;

		for (int i = 0; i < n; i++) {
			if(time[i] <= t) {
				answer = Math.min(answer, c[i]);
			}
		}

