public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    int A = sc.nextInt();
    int B = sc.nextInt();
    int C = sc.nextInt();
    int X = sc.nextInt();
    int Y = sc.nextInt();

    // A * X -> AX yen;
    // B * Y -> BY yen;
    // C * Math.max(X, Y) * 2 -> 2 * C * Math.max(X, Y) yen

    // O(n) -> 5000 * 5000 * 5000 -> 125 * 10^9 (NG)
    // O(n) -> 5000 * 5000 -> 25 * 10^6 (OK)

    long minValue = Integer.MAX_VALUE;
    for(int i = 0; i <= 5000; i++){
      for (int j = 0; j <= 5000; j++) {
        long aPizza = A * i;
        long bPizza = B * j;
        // X Y で不足しているpizzaをcとして計算
        long cPizza = 0;
        if (X - i > 0) {
          cPizza = C * (X - i) * 2;
        }
        if (Y - j > 0) {
          cPizza = Math.max(cPizza, C * (Y - j ) * 2);
        }

        minValue = Math.min(minValue, aPizza + bPizza + cPizza);
      }
    }

    System.out.println(minValue);
 }
}

import java.io.*;
import java.nio.CharBuffer;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.NoSuchElementException;

public class Main {

    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        ArrayList<Integer> d = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            int t = scanner.nextInt();
            d.add(t);
        }
        d.sort(Comparator.naturalOrder());
        writer.println(d.get(n / 2) - d.get(n / 2 - 1));

        writer.close();
    }

    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

