      long numC = (b-a+1)/c;
      if ((b-a+1)%c != 0) {
         int flag = 0;
         for (long i=a; i<a+c-1; i++) {
            if(i%c==0){
               flag = 1;
               break;
            }
         }
         if (flag == 1) {
            numC++;
         }
      }
      //System.out.prlongln(numC);
      long numD = (b-a+1)/d;
      if ((b-a+1)%d != 0) {
         int flag = 0;
         for (long i=a; i<a+d-1; i++) {
            if(i%d==0){
               flag = 1;
               break;
            }
         }
         if (flag == 1) {
            numD++;
         }
      }
      //System.out.prlongln(numD);
      long Lcd = lcm(c,d);
      long numC_D = (b-a+1)/Lcd;
      //System.out.prlongln(numC_D);
      if ((b-a+1)%Lcd != 0) {
         int flag = 0;
         for (long i=a; i<a+Lcd-1; i++) {
