        public void solve(Scanner sc, PrintWriter out) {
            int k = nint(sc);
            int s = nint(sc);
            int count = 0;
            for (int i = 0; i <= k; i++) {
                for (int j = 0; j <= k; j++) {
                    if(s-i-j<=k && 0 <= s-i-j){
                        count ++;
                    }
                }
            }
            out.println(count);

        }

