			while(true){
				boolean isTheSameSet = true;
				for(int y = 0;y < 2;y++){
					for(int x = 0;x < length;x++){
						if(RLSet[x] == 'R'){
							children[(y+1)%2][x+1] += children[y%2][x];
							children[y%2][x] = 0;
						}
						else{
							children[(y+1)%2][x-1] += children[y%2][x];
							children[y%2][x] = 0;
						}
					}
				}
				for(int x = 0;x < length;x++){
					if(children[0][x] != copyChildren[x])isTheSameSet = false;
					copyChildren[x] = children[0][x];
				}
				if(isTheSameSet)break;
			}
		}
