class Bridge{

	int x;
	int y;

	Bridge(int x, int y){
		this.x = x;
		this.y = y;
	}
}

class Lot{

	Bridge[] bridges;

	Lot(Bridge... b){
		this.bridges = b;
	}

	int lot(int num){
		int result = num;
		for(Bridge b: this.bridges){
			if(result == b.x)
				result = b.y;
			else if(result == b.y) result = b.x;
		}
		return result;
	}

}

