        //配列に格納
        for(int i=0;i<number;i++){
            rate[i] = Integer.parseInt((String)reader.readLine());
        }

        //最大・最小の判定
        maximum = doMax(rate);
        minimum = doMin(rate);

        gap = maximum - minimum;

        System.out.println(gap);
    }



    public static int doMax(int[] rate){
        maximum = rate[0];

        for(int i=1;i<rate.length;i++){
        if(maximum <= rate[i]){
            maximum = rate[i];
        }
        }
        return maximum;
    }


    public static int doMin(int[] rate){
        minimum = rate[0];

        for(int i=1;i<rate.length;i++){
            if(minimum >= rate[i]){
                minimum = rate[i];
            }
        }
        return minimum;
    }
}

