		N = scan.nextInt();
		K = scan.nextInt();
		S = scan.next();

		char[] charArray = S.toCharArray();
		String smallChar = String.valueOf(charArray[K - 1]).toLowerCase();

		char[] tmpcharArray = smallChar.toCharArray();
		charArray[K - 1] = tmpcharArray[0];

		System.out.println(new String(charArray));
