			long afactor = a / gcd;
			long bfactor = b / gcd;
			System.out.println(afactor);
			System.out.println(bfactor);

			System.out.println(gcd * afactor * bfactor);

		}
	}

	public static long gcd(long a, long b) {
		if ( a > b ) {
			return gcd(b, a);
		}

		if ( b % a == 0) {
			return a;
		}
		else {
			return gcd(a, b % a);
		}
	}

}

