		for (int i = 0; i < N ; i++) A[i] = sc.nextInt();
		int max = (K - A[N-1]) + A[0];
		for (int i = 1; i < N; i++) {
				int m = A[i] - A[i-1];
				if (max < m) max = m;
		}
		System.out.println(K - max);
	}
}

