class AtCoder {

    int N, M;
    Map<Integer, Integer> map;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        M = sc.nextInt();
        map = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int K = sc.nextInt();
            for (int j = 0; j < K; j++) {
                int m = sc.nextInt();
                if (!map.containsKey(m)) {
                    map.put(m, 1);
                } else {
                    map.put(m, map.get(m) + 1);
                }
            }
        }
    }

    void solve(PrintWriter out) {
        int cnt = 0;
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            if (e.getValue() == N) cnt++;
        }
        out.println(cnt);
    }

}

