    static class BDigitSums {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long n = in.nextInt();

            boolean answer = n % s(n) == 0;

            out.println(answer ? "Yes" : "No");
        }

        static long s(long n) {
            long sum = 0;
            while (n > 0) {
                sum += (n % 10);
                n /= 10;
            }
            return sum;
        }

