		int t1 = -1,t2 = -1;
		for(int i=0;i<N-1;i++) {
			if(A[i] > A[i+1]) {
				t1 = i;
				for(int j=i+1;j<N-1;j++) {
					if(A[j] > A[j+1]) {
						t2 = j+1;
					}
				}
				break;
			}
		}
		if(t1 != -1&&t2 != -1) {
			int tmp = A[t1];
			A[t1] = A[t2];
			A[t2] = tmp;
		}
		for(int i=0;i<N-1;i++) {
