                long need = (rh+a-1)/a;
                ans += need;
                // bsearch for monster index whose 'x' is > [curr.x + 2*d]
                if(j < i)
                    j=i;
                for(; j < n && mons[j].x <= (curr.x + 2*d); ++j);
                dp[i] += (need*a);
                dp[j] -= (need*a);
            }
            dp[i+1] += dp[i];
        }
        System.out.println(ans);
    }
}

class Monster implements Comparable<Monster>{
