    public static int isPower(int num) {
        for (int n = 2; Math.pow(num, 1.0 / n) >= 2.0; n++) {
            double nThRoot = Math.pow(num, 1.0 / n);
            if (nThRoot==Math.floor(nThRoot))
                return (int)Math.pow(nThRoot, n);
        }
        return -1;
    }
}

