        long a,b;


        while((str=br.readLine()) != null){
            a = Long.parseLong(str.substring(0, str.indexOf(" ")));
            b = Long.parseLong(str.substring(str.indexOf(" ")+1, str.length()));

            System.out.println(gcd(a, b) + " " + lcm(a,b));

        }
    }

	private static long gcd(long a, long b){
		if (b == 0) return a;
		return gcd(b, a % b);
	}

