        List<String> bArray = new ArrayList<>();
        List<String> cArray = new ArrayList<>();

        for(char c: A){
            String s = String.valueOf(c);
            aArray.add(s);
        }
        for(char c: B){
            String s = String.valueOf(c);
            bArray.add(s);
        }
        for(char c: C){
            String s = String.valueOf(c);
            cArray.add(s);
        }

        String next = aArray.get(0);
        aArray.remove(0);

        String ans = "";

        while(true){
            if(next.equals("a")){
                if(aArray.size() == 0){
                    ans = "A";
                    break;
                }
                next = aArray.get(0);
                aArray.remove(0);
            } else if(next.equals("b")){
                if(bArray.size() == 0){
                    ans = "B";
                    break;
                }
                next = bArray.get(0);
                bArray.remove(0);
            } else {
                if(cArray.size() == 0){
                    ans = "C";
                    break;
                }
                next = cArray.get(0);
                cArray.remove(0);
            }
        }

        System.out.println(ans);
    }
}

