    static Integer[] memo=new Integer[100005];
    static int dp(int x,int n,int[] h){
        if (x==n-1)return 0;
        if (memo[x]!=Integer.MAX_VALUE){
            return memo[x];
        }
        for (int i = 1; i <=k1 ; i++) {
            if (x+i<n)memo[x]=Math.min(memo[x],dp(x+i,n,h)+Math.abs(h[x]-h[x+i]));
        }
        return memo[x];

