	}
}

class Methods{
	node head;
	int size =0 ;
	void insert(int data) {
		node n = new node(data);
		size++;
		if(head==null) {
			head= n;
		}
		else {
			node k = head;
			while(k.next!=null) {
				k=k.next;
			}

			k.next=n;
		}

	}

	void print() {
		node n = head;
		while(n.next!=null) {
			System.out.print(n.data+" ");
			n=n.next;
		}
		System.out.println(n.data);

	}

	void isLoop(int x) {

		System.out.println(size - x +1);

		node n = head;

		while(n.next!=null && x-->2 ) {
			n=n.next;
		}

		n.next=n.next.next;

	}


}

