    static class Task {
        long A, B;

        void solve(InputReader in, PrintWriter out) {
            A = in.nextLong();
            B = in.nextLong();

            out.println((A + B) % 2 == 0 ? (A + B)/2 : "IMPOSSIBLE");
        }

