        for (int i = 1; i < max_i; i++) {
            if (numbers[i] < min) {
                min = numbers[i];
                min_i = i;

                int j;
                for (j = max_i; j > min_i; j--) {
                    if (numbers[j] > max) {
                        max = numbers[j];
                        max_i = j;
                        break;
                    }
                }

                if (j == min_i) {
                  break;
                }
            }
        }

        System.out.println(max - min);
    }
}

