		public void solve(int testNumber, MyScanner in, PrintWriter out)
		{
			int n = in.nextInt();
			long ans = 0;
			int max = 0;
			for( int i=0; i<n; i++ )
			{
				int a = in.nextInt();
				ans += Math.max(0, max-a);
				max = Math.max(max, a);
			}
			out.println(ans);
		}
