    public static int countSumOfThree(int max, int sumAns){
        int count = 0;
        for(int i=0; i<=max; i++){
            for(int j=0; j<=max; j++){
                for(int k=0; k<=max; k++){
                    if(i+j+k == sumAns) count++;
                }
            }
        }
        return count;
    }
