		try {
			scanner = new Scanner(System.in);
			numFrog = scanner.nextInt();
			int[] heightArray = new int[numFrog];
			int[] costAr = new int[numFrog];

			for (int i = 0; i < numFrog; i++) {
				heightArray[i] = scanner.nextInt();
			}

			Arrays.fill(costAr, 999999);
			costAr[0] = 0;
			for (int i = 0; i < heightArray.length; i++) {
				for (int j = 1; j <= jump; j++) {
					if (i + j == heightArray.length) {
						break;
					}
					int wkRes = Math.abs(heightArray[i + j] - heightArray[i]);
					costAr[i + j] = Math.min(wkRes + costAr[i], costAr[i + j]);
				}
			}

			System.out.println(costAr[costAr.length - 1]);

		} finally {
			if (scanner != null) {
				scanner.close();
			}
		}
	}
}

