public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      int N = in.nextInt();
      int[] A = new int[N];

      insertionSort(A, N);

//      End solve()
    }

    void insertionSort(int[] A, int N) {
      for (int i = 1; i < N; i++) {
        int v = A[i];
        int j = i - 1; 
        while (j >= 0 && A[j] > j) {
          A[j+1] = A[j];
          j--;
        }
        A[j+1] =v;

        for (int k = 0; k < N; k++) {
          out.print(A[k]);
          if (k != N - 1) {
            out.print(" ");
          } else {
            out.print("\n");
          }
        }
      }

    }


//    End Solution
}


