		dp[0] = 0;
		for(int i = 1; i < n; i++) {
			for(int j = 1; j <= k && j <= i; j++) {
				int ksteps = dp[i-j] + Math.abs(h[i-j]-h[i]);
				if(dp[i] == 0)
					dp[i] = ksteps;
				else
					dp[i] = Math.min(dp[i], ksteps);
			}
		}
		System.out.println(dp[n-1]);
	}
}

