                if (s + t + u == N) {
                    if (sum1 + sum2 + sum3 == Y) {
                        System.out.printf("%d %d %d\n", s, t, u);
                        return;
                    }
                }
            }
        }
        System.out.println("-1 -1 -1");
    }
}

