      int tmp = x - i;
      if (tmp < 0) {
        break;
      }
      if (!ps.contains(tmp)) {
        min = tmp;
        break;
      }
    }

    if (Math.abs(x - min) <= Math.abs(x - max)) {
      System.out.println(min);
    } else {
      System.out.println(max);
    }
  }
}

