	static String sort(String str){
		StringBuilder sb=new StringBuilder(str);
		if(sb.charAt(0)>sb.charAt(1)){
			sb.insert(2,sb.charAt(0));
			sb.deleteCharAt(0);
		}
		if(sb.charAt(1)>sb.charAt(2)){
			sb.insert(1,sb.charAt(2));
			sb.deleteCharAt(3);
		}
		if(sb.charAt(0)>sb.charAt(1)){
			sb.insert(2,sb.charAt(0));
			sb.deleteCharAt(0);
		}
