        double right = (W - x) * H;
        double tmp;
        if (left <= 0.0) {
            tmp = right;
        } else if (right <= 0.0) {
            tmp = left;
        } else {
            if (left > right) {
                tmp = right;
            } else {
                tmp = left;
            }
