        double tmp2;
        if (up <= 0.0) {
            tmp2 = down;
        } else if (down <= 0.0) {
            tmp2 = up;
        } else {
            if (up > down) {
                tmp2 = down;
            } else {
                tmp2 = up;
            }
        }

        if (tmp == tmp2) {
            System.out.print(String.format("%.9f", tmp));
