      Ave = 0;
      Sum = 0;
      if(Num==0){
        break;
      }
      for(int i=0;i<Num;i++){
        N[i] = scanner.nextInt();
        Ave += N[i];
      }
      Ave /= Num;

      for(int i=0;i<Num;i++){
        Sum += (N[i]-Ave)*(N[i]-Ave);
      }

      SD[K] = Math.sqrt(Sum/Num);
      K++;
    }

    for(int i=0;i<K;i++){
      System.out.println(SD[i]);
    }

  }
}

