		int N = sc.nextInt();

		int[][] A=new int[2][N];

		for (int i = 0; i < 2; i++) {

			for (int j = 0; j < N; j++) {
				A[i][j]=sc.nextInt();
			}

		}

		int[][] dp=new int[2][N];

		dp[0][0]=A[0][0];

		for (int i = 1; i < N; i++) {
			dp[0][i]=dp[0][i-1]+A[0][i];
		}

			dp[1][0]=dp[0][0]+A[1][0];

		for (int i = 1; i < N; i++) {
			dp[1][i]=A[1][i]+Math.max(dp[1][i-1],dp[0][i]);
		}

		int ans=dp[1][N-1];

		System.out.println(ans);
	}

	//以下テンプレート

	public static int[] extgcd(int a, int b) {

		int x0 = 1;
		int x1 = 0;

		int y0 = 0;
		int y1 = 1;

		while (b != 0) {
			int q = a / b;
			int r = a % b;

			int x2 = x0 - q * x1;
			int y2 = y0 - q * y1;

			a = b;
			b = r;

			x0 = x1;
			x1 = x2;

			y0 = y1;
			y1 = y2;
		}

		return new int[] { a, x0, y0 };

	}

	static int gcd(int a, int b) {

		if (b == 0)
			return a;

		if (a < b) {
			int t = a;
			a = b;
			b = t;
		}

		return gcd(b, a % b);

	}

	static int lcm(int a, int b) {
		return a * b / gcd(a, b);
	}

	static void swap(int[] a) {
		int t;

		t = a[0];
		a[0] = a[1];
		a[1] = t;

		return;
	}

	static <T> void output(List<T> list) {

		for (int i = 0; i < list.size(); i++) {
			System.out.print(list.get(i));

