	public static void sort(int array[][], int n) {

		if (array == null) {
			return;
		}

		for (int i = 0; i < n; i++) {
			for (int j = n - 1; j > i; j--) {
				if (array[0][j] < array[0][j-1]) {
					int temp0 = array[0][j];
					int temp1 = array[1][j];

					array[0][j] = array[0][j-1];
					array[1][j] = array[1][j-1];

					array[0][j-1] = temp0;
					array[1][j-1] = temp1;
				}
			}
		}

		return;
	}

}

