    static class Solver {

    	public void solve(int testNumber, MyInput in, PrintWriter out) {
			String ans = null;
			String ABCD = in.nextString();
			int[] x = new int[4];
			for(int i=0; i < 4; i++){
				x[i] = ABCD.charAt(i) - '0';
			}
			int total = 0;
			boolean[] op = new boolean[3];
			for(int i = 0; i < (1 << 3); i++) {
				total = x[0];
				for(int j=0; j < 3; j++) {
					if((i & (1 << j)) != 0) {
						total += x[j+1];
						op[j] = true;
					} else {
						total -= x[j+1];
						op[j] = false;
					}
				}
				if(total == 7) {
					break;
				}
			}
			ans = String.valueOf(x[0]);
			for(int i=0; i < 3; i++) {
				if(op[i]) {
					ans = ans + "+" + x[i+1];
				} else {
					ans = ans + "-" + x[i+1];
				}
			}
			ans = ans + "=7";
			out.println(ans);
        }
    }
