		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int h = new int[N];
		int dp = new int[N];
		for(int i = 0;i < N;i++){
			h[i] = sc.nextInt();
		}
		dp[0] = 0;
		dp[1] = (int)Math.abs(h[1] - h[0]);
		for(int i = 2;i < N;i++){
			dp[i] = 100000;
			for(int j = 1;j < K + 1;j++){
