  public static int solve(int n,int h[]){
    int[] dp = new int[n];
  	dp[1] = Math.abs(h[1]-h[0]);
  	for(int i=1;i<n;i++)
      dp[i] = Math.min(Math.abs(h[i]-h[i-1])+dp[i-1],Math.abs(h[i]-h[i-2])+dp[i-2]);
    return dp[n-1];
  }
}

