    String[] names = new String[n];
    int[] lefttime = new int[n];
    for(int i = 0; i < n; i++){
      names[i] = sc.nextStr();
      lefttime[i] = sc.nextInt();
    }

    LinkedList<Integer> queue = new LinkedList<Integer>();
    for(int i = 0; i < n; i++){
      queue.add(i);
    }
    int nowtime = 0;
    while(!queue.isEmpty()){
      int nownum = queue.poll();
      if(lefttime[nownum] > q){
        lefttime[nownum] -= q;
        nowtime += q;
        queue.add(nownum);
