	    static  void dfs(int n,boolean flag,ArrayList<ArrayList<Integer>> adj,int src,boolean vis[],ArrayList<Integer> centroid,int size[]) {
	        vis[src]=true;
	        size[src]=1;
	        for(int i:adj.get(src)) {
	          if(vis[i]==false){
	            dfs(n,flag,adj,i,vis,centroid,size);
	            size[src]+=size[i];
	            if(size[i]>n/2) {
	              flag=false;
	            }
	          }
	        }
	        if(n-size[src]>n/2) {
	          flag=false;
	        }
	        if(flag==true) {
	          centroid.add(src);
	        }
	    }



