public class Main {

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		String s = sc.next();
		Stack<Integer> stack = new Stack<Integer>();
		stack.push(s.charAt(0)-'0');
		int count =0;
		for(int i=1;i<s.length();i++) {
			if (stack.isEmpty()) {
				stack.push(s.charAt(i)-'0');
			} else {
				if (stack.peek()!=(s.charAt(i)-'0')) {
					stack.pop();
					count+=2;
				} else {
					stack.push(s.charAt(i)-'0');
				}
			}
		}
		System.out.println(count);
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long N = in.nextLong();
        long K = in.nextLong();

        if (K == 1) {
            System.out.println(K);
            return;
        }

        long slow = absoluteDiff(N, K);
        long fast = absoluteDiff(absoluteDiff(N, K), K);
        long min = slow;

        while (slow != fast) {
            min = Math.min(Math.min(min, slow), fast);
            slow = absoluteDiff(slow, K);
            fast = absoluteDiff(absoluteDiff(fast, K), K);
        }

        System.out.println(min);

    }

    public static long absoluteDiff(long a, long b) {
        return Math.abs(a - b);
    }

}

